package com.pousada.service;

import com.pousada.domain.RatePlan;
import com.pousada.domain.Reservation;
import com.pousada.domain.ReservationStatus;
import com.pousada.domain.Room;
import com.pousada.domain.RoomType;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;

public class ReservationService {
    private final List<Reservation> reservations;
    private final RoomService roomService;
    private final PricingService pricingService;

    public ReservationService(RoomService roomService, PricingService pricingService) {
        this.reservations = new ArrayList<>();
        this.roomService = roomService;
        this.pricingService = pricingService;
    }

    public Reservation createReservation(int roomNumber, LocalDate checkIn, LocalDate checkOut,
                                        int guestCount, String guestEmail, String guestIdentification,
                                        String guestIdentificationType, RatePlan ratePlan) {
        // Validate room exists
        Room room = roomService.getRoomByNumber(roomNumber)
            .orElseThrow(() -> new IllegalArgumentException("Room not found: " + roomNumber));

        // Validate room capacity
        if (guestCount > room.getType().getCapacity()) {
            throw new IllegalArgumentException("Guest count exceeds room capacity");
        }

        // Validate dates
        if (checkOut.isBefore(checkIn) || checkOut.isEqual(checkIn)) {
            throw new IllegalArgumentException("Check-out must be after check-in");
        }

        // Validate room availability
        if (!isRoomAvailable(roomNumber, checkIn, checkOut)) {
            throw new IllegalArgumentException("Room is not available for the requested dates");
        }

        // Calculate price
        double totalPrice = pricingService.calculatePrice(room.getType(), checkIn, checkOut, ratePlan);

        // Create reservation
        Reservation reservation = new Reservation(roomNumber, checkIn, checkOut, guestCount,
            guestEmail, guestIdentification, guestIdentificationType, ratePlan, totalPrice);

        reservations.add(reservation);
        return reservation;
    }

    public Optional<Reservation> getReservationById(String id) {
        return reservations.stream()
            .filter(res -> res.getId().equals(id))
            .findFirst();
    }

    public List<Reservation> getAllReservations() {
        return new ArrayList<>(reservations);
    }

    public void confirmReservation(String id) {
        Reservation reservation = getReservationById(id)
            .orElseThrow(() -> new IllegalArgumentException("Reservation not found: " + id));
        reservation.confirm();
    }

    public void checkInReservation(String id) {
        Reservation reservation = getReservationById(id)
            .orElseThrow(() -> new IllegalArgumentException("Reservation not found: " + id));
        reservation.checkIn();
    }

    public void checkOutReservation(String id) {
        Reservation reservation = getReservationById(id)
            .orElseThrow(() -> new IllegalArgumentException("Reservation not found: " + id));
        reservation.checkOut();
    }

    public void cancelReservation(String id) {
        Reservation reservation = getReservationById(id)
            .orElseThrow(() -> new IllegalArgumentException("Reservation not found: " + id));
        reservation.cancel();
    }

    private boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
        return reservations.stream()
            .filter(res -> res.getRoomNumber() == roomNumber)
            .filter(res -> res.getStatus() != ReservationStatus.CANCELLED)
            .noneMatch(res -> datesOverlap(checkIn, checkOut, res.getCheckIn(), res.getCheckOut()));
    }

    private boolean datesOverlap(LocalDate checkIn1, LocalDate checkOut1, LocalDate checkIn2, LocalDate checkOut2) {
        return !checkOut1.isBefore(checkIn2) && !checkOut2.isBefore(checkIn1);
    }
}

package com.pousada.service;

import com.pousada.domain.Reservation;
import com.pousada.domain.ReservationStatus;
import com.pousada.domain.Room;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.Collectors;

public class ReportService {
    private final ReservationService reservationService;
    private final RoomService roomService;

    public ReportService(ReservationService reservationService, RoomService roomService) {
        this.reservationService = reservationService;
        this.roomService = roomService;
    }

    public String generateOccupancyReport(LocalDate startDate, LocalDate endDate) {
        StringBuilder report = new StringBuilder();
        report.append("Date,Room,Status\n");

        List<Room> rooms = roomService.getAllRooms();
        List<Reservation> reservations = reservationService.getAllReservations();

        LocalDate currentDate = startDate;
        while (!currentDate.isAfter(endDate)) {
            for (Room room : rooms) {
                String status = "Available";
                for (Reservation reservation : reservations) {
                    if (reservation.getRoomNumber() == room.getNumber() &&
                        !currentDate.isBefore(reservation.getCheckIn()) &&
                        currentDate.isBefore(reservation.getCheckOut()) &&
                        reservation.getStatus() != ReservationStatus.CANCELLED) {
                        status = "Occupied";
                        break;
                    }
                }
                report.append(currentDate).append(",").append(room.getNumber()).append(",").append(status).append("\n");
            }
            currentDate = currentDate.plusDays(1);
        }

        return report.toString();
    }

    public String generateRevenueReport(LocalDate startDate, LocalDate endDate) {
        StringBuilder report = new StringBuilder();
        report.append("Date,Revenue\n");

        List<Reservation> reservations = reservationService.getAllReservations()
            .stream()
            .filter(res -> res.getStatus() == ReservationStatus.CHECKED_OUT)
            .filter(res -> !res.getCheckOut().isBefore(startDate) && !res.getCheckIn().isAfter(endDate))
            .collect(Collectors.toList());

        LocalDate currentDate = startDate;
        while (!currentDate.isAfter(endDate)) {
            double dailyRevenue = 0;
            final LocalDate date = currentDate;
            for (Reservation res : reservations) {
                if (!date.isBefore(res.getCheckIn()) && date.isBefore(res.getCheckOut())) {
                    dailyRevenue += calculateDailyRevenue(res, date);
                }
            }
            report.append(currentDate).append(",").append(String.format("%.2f", dailyRevenue)).append("\n");
            currentDate = currentDate.plusDays(1);
        }

        return report.toString();
    }

    private double calculateDailyRevenue(Reservation reservation, LocalDate date) {
        long totalDays = java.time.temporal.ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
        return reservation.getTotalPrice() / totalDays;
    }
}

