package com.pousada.controller;

import com.pousada.domain.RatePlan;
import com.pousada.domain.Reservation;
import com.pousada.dto.CreateReservationRequest;
import com.pousada.dto.DocumentResponse;
import com.pousada.dto.ErrorResponse;
import com.pousada.dto.ReservationResponse;
import com.pousada.service.DocumentService;
import com.pousada.service.ReservationService;
import io.javalin.http.Context;
import io.javalin.http.HttpStatus;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.Collectors;

public class ReservationController {
    private final ReservationService reservationService;
    private final DocumentService documentService;

    public ReservationController(ReservationService reservationService, DocumentService documentService) {
        this.reservationService = reservationService;
        this.documentService = documentService;
    }

    public void createReservation(Context ctx) {
        try {
            CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);

            Reservation reservation = reservationService.createReservation(
                request.getRoomNumber(),
                LocalDate.parse(request.getCheckIn()),
                LocalDate.parse(request.getCheckOut()),
                request.getGuestCount(),
                request.getGuestEmail(),
                request.getGuestIdentification(),
                request.getGuestIdentificationType(),
                RatePlan.valueOf(request.getRatePlan())
            );

            ctx.status(HttpStatus.CREATED);
            ctx.json(toResponse(reservation));
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.BAD_REQUEST);
            ctx.json(new ErrorResponse("BAD_REQUEST", e.getMessage()));
        } catch (Exception e) {
            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
            ctx.json(new ErrorResponse("INTERNAL_SERVER_ERROR", e.getMessage()));
        }
    }

    public void getReservation(Context ctx) {
        try {
            String id = ctx.pathParam("id");
            Reservation reservation = reservationService.getReservationById(id)
                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));

            ctx.json(toResponse(reservation));
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.NOT_FOUND);
            ctx.json(new ErrorResponse("NOT_FOUND", e.getMessage()));
        }
    }

    public void getAllReservations(Context ctx) {
        List<ReservationResponse> reservations = reservationService.getAllReservations()
            .stream()
            .map(this::toResponse)
            .collect(Collectors.toList());

        ctx.json(reservations);
    }

    public void confirmReservation(Context ctx) {
        try {
            String id = ctx.pathParam("id");
            reservationService.confirmReservation(id);

            Reservation reservation = reservationService.getReservationById(id)
                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));

            ctx.json(toResponse(reservation));
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.NOT_FOUND);
            ctx.json(new ErrorResponse("NOT_FOUND", e.getMessage()));
        } catch (IllegalStateException e) {
            ctx.status(HttpStatus.BAD_REQUEST);
            ctx.json(new ErrorResponse("BAD_REQUEST", e.getMessage()));
        }
    }

    public void checkInReservation(Context ctx) {
        try {
            String id = ctx.pathParam("id");
            reservationService.checkInReservation(id);

            Reservation reservation = reservationService.getReservationById(id)
                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));

            ctx.json(toResponse(reservation));
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.NOT_FOUND);
            ctx.json(new ErrorResponse("NOT_FOUND", e.getMessage()));
        } catch (IllegalStateException e) {
            ctx.status(HttpStatus.BAD_REQUEST);
            ctx.json(new ErrorResponse("BAD_REQUEST", e.getMessage()));
        }
    }

    public void checkOutReservation(Context ctx) {
        try {
            String id = ctx.pathParam("id");
            reservationService.checkOutReservation(id);

            Reservation reservation = reservationService.getReservationById(id)
                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));

            ctx.json(toResponse(reservation));
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.NOT_FOUND);
            ctx.json(new ErrorResponse("NOT_FOUND", e.getMessage()));
        } catch (IllegalStateException e) {
            ctx.status(HttpStatus.BAD_REQUEST);
            ctx.json(new ErrorResponse("BAD_REQUEST", e.getMessage()));
        }
    }

    public void cancelReservation(Context ctx) {
        try {
            String id = ctx.pathParam("id");
            reservationService.cancelReservation(id);

            Reservation reservation = reservationService.getReservationById(id)
                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));

            ctx.json(toResponse(reservation));
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.NOT_FOUND);
            ctx.json(new ErrorResponse("NOT_FOUND", e.getMessage()));
        } catch (IllegalStateException e) {
            ctx.status(HttpStatus.BAD_REQUEST);
            ctx.json(new ErrorResponse("BAD_REQUEST", e.getMessage()));
        }
    }

    public void generateDocument(Context ctx) {
        try {
            String id = ctx.pathParam("id");
            Reservation reservation = reservationService.getReservationById(id)
                .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));

            var documentContent = documentService.generateDocument(reservation);

            DocumentResponse response = new DocumentResponse(
                documentContent.documentId(),
                documentContent.guestName(),
                documentContent.guestIdentification(),
                documentContent.roomNumber(),
                documentContent.checkIn(),
                documentContent.checkOut(),
                documentContent.totalPrice(),
                documentContent.text()
            );

            ctx.json(response);
        } catch (IllegalArgumentException e) {
            ctx.status(HttpStatus.NOT_FOUND);
            ctx.json(new ErrorResponse("NOT_FOUND", e.getMessage()));
        } catch (Exception e) {
            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR);
            ctx.json(new ErrorResponse("INTERNAL_SERVER_ERROR", e.getMessage()));
        }
    }

    private ReservationResponse toResponse(Reservation reservation) {
        return new ReservationResponse(
            reservation.getId(),
            reservation.getRoomNumber(),
            reservation.getCheckIn().toString(),
            reservation.getCheckOut().toString(),
            reservation.getGuestCount(),
            reservation.getGuestEmail(),
            reservation.getGuestIdentification(),
            reservation.getGuestIdentificationType(),
            reservation.getRatePlan().toString(),
            reservation.getTotalPrice(),
            reservation.getStatus().toString()
        );
    }
}

package com.pousada.controller;

import com.pousada.service.ReportService;
import io.javalin.http.Context;
import java.time.LocalDate;

public class ReportController {
    private final ReportService reportService;

    public ReportController(ReportService reportService) {
        this.reportService = reportService;
    }

    public void getOccupancyReport(Context ctx) {
        try {
            String startDate = ctx.queryParam("startDate");
            String endDate = ctx.queryParam("endDate");

            if (startDate == null || endDate == null) {
                ctx.status(400);
                ctx.json(new java.util.HashMap<String, String>() {{
                    put("error", "BAD_REQUEST");
                    put("message", "startDate and endDate query parameters are required");
                }});
                return;
            }

            LocalDate start = LocalDate.parse(startDate);
            LocalDate end = LocalDate.parse(endDate);

            String report = reportService.generateOccupancyReport(start, end);
            ctx.contentType("text/csv");
            ctx.result(report);
        } catch (Exception e) {
            ctx.status(500);
            ctx.json(new java.util.HashMap<String, String>() {{
                put("error", "INTERNAL_SERVER_ERROR");
                put("message", e.getMessage());
            }});
        }
    }

    public void getRevenueReport(Context ctx) {
        try {
            String startDate = ctx.queryParam("startDate");
            String endDate = ctx.queryParam("endDate");

            if (startDate == null || endDate == null) {
                ctx.status(400);
                ctx.json(new java.util.HashMap<String, String>() {{
                    put("error", "BAD_REQUEST");
                    put("message", "startDate and endDate query parameters are required");
                }});
                return;
            }

            LocalDate start = LocalDate.parse(startDate);
