import com.pousada.service.RoomService;
import io.javalin.Javalin;

public class Application {
    public static void main(String[] args) {
        // Initialize services
        RoomService roomService = new RoomService();
        PricingService pricingService = new PricingService();
        ReservationService reservationService = new ReservationService(roomService, pricingService);
        MessageService messageService = new MessageService();
        DocumentService documentService = new DocumentService();
        ReportService reportService = new ReportService(reservationService, roomService);

        // Initialize controllers
        RoomController roomController = new RoomController(roomService);
        ReservationController reservationController = new ReservationController(reservationService, documentService);
        ReportController reportController = new ReportController(reportService);
        MessageController messageController = new MessageController(messageService);

        // Get port from environment or use default
        String portEnv = System.getenv("PORT");
        int port = portEnv != null ? Integer.parseInt(portEnv) : 7070;

        // Create and start Javalin app
        Javalin app = Javalin.create();

        // Room endpoints
        app.get("/rooms", roomController::getAllRooms);

        // Reservation endpoints
        app.post("/reservations", reservationController::createReservation);
        app.get("/reservations", reservationController::getAllReservations);
        app.get("/reservations/{id}", reservationController::getReservation);
        app.post("/reservations/{id}/confirm", reservationController::confirmReservation);
        app.post("/reservations/{id}/check-in", reservationController::checkInReservation);
        app.post("/reservations/{id}/check-out", reservationController::checkOutReservation);
        app.post("/reservations/{id}/cancel", reservationController::cancelReservation);
        app.get("/reservations/{id}/document", reservationController::generateDocument);

        // Report endpoints
        app.get("/reports/occupancy", reportController::getOccupancyReport);
        app.get("/reports/revenue", reportController::getRevenueReport);

        // Message endpoints
        app.get("/messages", messageController::getAllMessages);

        app.start(port);
    }
}

