45	    private void createReservation(io.javalin.http.Context ctx) {
46	        try {
47	            CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
48	
49	            if (req.roomNumber == 0 || req.guestName == null || req.guestEmail == null || req.checkIn == null
50	                    || req.checkOut == null || req.guests == 0 || req.ratePlan == null) {
51	                ctx.status(400);
52	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Missing required fields"));
53	                return;
54	            }
55	
56	            int identificationCount = (req.guestCpf != null ? 1 : 0) + (req.companyCnpj != null ? 1 : 0)
57	                    + (req.guestPassport != null ? 1 : 0);
58	            if (identificationCount != 1) {
59	                ctx.status(400);
60	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Exactly one of guestCpf, companyCnpj, or guestPassport must be provided"));
61	                return;
62	            }
63	
64	            if (req.companyCnpj != null && req.companyName == null) {
65	                ctx.status(400);
66	                ctx.json(new ErrorResponse("INVALID_REQUEST", "companyName is required when companyCnpj is provided"));
67	                return;
68	            }
69	
70	            if (req.guestPassport != null && req.guestCountry == null) {
71	                ctx.status(400);
72	                ctx.json(new ErrorResponse("INVALID_REQUEST", "guestCountry is required when guestPassport is provided"));
73	                return;
74	            }
75	
76	            LocalDate checkIn, checkOut;
77	            try {
78	                checkIn = LocalDate.parse(req.checkIn, DATE_FORMAT);
79	                checkOut = LocalDate.parse(req.checkOut, DATE_FORMAT);
80	            } catch (DateTimeParseException e) {
81	                ctx.status(400);
82	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format, use yyyy-MM-dd"));
83	                return;
84	            }
85	
86	            if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
87	                ctx.status(400);
88	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Check-out must be after check-in"));
89	                return;
90	            }
91	
92	            RatePlan ratePlan;
93	            try {
94	                ratePlan = RatePlan.valueOf(req.ratePlan);
95	            } catch (IllegalArgumentException e) {
96	                ctx.status(400);
97	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid rate plan"));
98	                return;
99	            }
100	
101	            try {
102	                Reservation reservation = reservationService.createReservation(req.roomNumber, req.guestName,
103	                        req.guestEmail, req.guestCpf, req.companyCnpj, req.companyName, req.guestPassport,
104	                        req.guestCountry, checkIn, checkOut, req.guests, ratePlan);
105	                ctx.status(201);
106	                ctx.json(ReservationResponse.fromReservation(reservation));
107	            } catch (IllegalArgumentException e) {
108	                String msg = e.getMessage();
109	                if (msg.equals("Room not found")) {
110	                    ctx.status(404);
111	                    ctx.json(new ErrorResponse("ROOM_NOT_FOUND", msg));
112	                } else if (msg.contains("unavailable")) {
113	                    ctx.status(409);
114	                    ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", msg));
115	                } else if (msg.equals("Invalid number of guests")) {
116	                    ctx.status(422);
117	                    ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", msg));
118	                } else {
119	                    ctx.status(400);
120	                    ctx.json(new ErrorResponse("INVALID_REQUEST", msg));
121	                }
122	            }
123	        } catch (JsonSyntaxException e) {
124	            ctx.status(400);
125	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid JSON"));
126	        }
127	    }
