package com.pousada.domain;

import java.time.LocalDate;
import java.util.UUID;

public class Reservation {
    private final String id;
    private final int roomNumber;
    private final LocalDate checkIn;
    private final LocalDate checkOut;
    private final int guestCount;
    private final String guestEmail;
    private final String guestIdentification;
    private final String guestIdentificationType;
    private final RatePlan ratePlan;
    private final double totalPrice;
    private ReservationStatus status;

    public Reservation(int roomNumber, LocalDate checkIn, LocalDate checkOut, int guestCount,
                      String guestEmail, String guestIdentification, String guestIdentificationType,
                      RatePlan ratePlan, double totalPrice) {
        this.id = UUID.randomUUID().toString();
        this.roomNumber = roomNumber;
        this.checkIn = checkIn;
        this.checkOut = checkOut;
        this.guestCount = guestCount;
        this.guestEmail = guestEmail;
        this.guestIdentification = guestIdentification;
        this.guestIdentificationType = guestIdentificationType;
        this.ratePlan = ratePlan;
        this.totalPrice = totalPrice;
        this.status = ReservationStatus.PENDING;
    }

    public String getId() {
        return id;
    }

    public int getRoomNumber() {
        return roomNumber;
    }

    public LocalDate getCheckIn() {
        return checkIn;
    }

    public LocalDate getCheckOut() {
        return checkOut;
    }

    public int getGuestCount() {
        return guestCount;
    }

    public String getGuestEmail() {
        return guestEmail;
    }

    public String getGuestIdentification() {
        return guestIdentification;
    }

    public String getGuestIdentificationType() {
        return guestIdentificationType;
    }

    public RatePlan getRatePlan() {
        return ratePlan;
    }

    public double getTotalPrice() {
        return totalPrice;
    }

    public ReservationStatus getStatus() {
        return status;
    }

    public void confirm() {
        if (status != ReservationStatus.PENDING) {
            throw new IllegalStateException("Only pending reservations can be confirmed");
        }
        this.status = ReservationStatus.CONFIRMED;
    }

    public void checkIn() {
        if (status != ReservationStatus.CONFIRMED) {
            throw new IllegalStateException("Only confirmed reservations can be checked in");
        }
        this.status = ReservationStatus.CHECKED_IN;
    }

    public void checkOut() {
        if (status != ReservationStatus.CHECKED_IN) {
            throw new IllegalStateException("Only checked-in reservations can be checked out");
        }
        this.status = ReservationStatus.CHECKED_OUT;
    }

    public void cancel() {
        if (status == ReservationStatus.CHECKED_OUT || status == ReservationStatus.CANCELLED) {
            throw new IllegalStateException("Cannot cancel a checked-out or already cancelled reservation");
        }
        this.status = ReservationStatus.CANCELLED;
    }

    public int getDurationInDays() {
        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    }
}

