package com.pousada.service;

import com.pousada.domain.Reservation;
import com.pousada.domain.ReservationStatus;
import com.pousada.domain.Room;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.Collectors;

public class ReportService {
    private final ReservationService reservationService;
    private final RoomService roomService;

    public ReportService(ReservationService reservationService, RoomService roomService) {
        this.reservationService = reservationService;
        this.roomService = roomService;
    }

    public String generateOccupancyReport(LocalDate startDate, LocalDate endDate) {
        StringBuilder report = new StringBuilder();
        report.append("Date,Room,Status\n");

        List<Room> rooms = roomService.getAllRooms();
        List<Reservation> reservations = reservationService.getAllReservations();

        LocalDate currentDate = startDate;
        while (!currentDate.isAfter(endDate)) {
            for (Room room : rooms) {
                String status = "Available";
                for (Reservation reservation : reservations) {
                    if (reservation.getRoomNumber() == room.getNumber() &&
                        !currentDate.isBefore(reservation.getCheckIn()) &&
                        currentDate.isBefore(reservation.getCheckOut()) &&
                        reservation.getStatus() != ReservationStatus.CANCELLED) {
                        status = "Occupied";
                        break;
                    }
                }
                report.append(currentDate).append(",").append(room.getNumber()).append(",").append(status).append("\n");
            }
            currentDate = currentDate.plusDays(1);
        }

        return report.toString();
    }

    public String generateRevenueReport(LocalDate startDate, LocalDate endDate) {
        StringBuilder report = new StringBuilder();
        report.append("Date,Revenue\n");

        List<Reservation> reservations = reservationService.getAllReservations()
            .stream()
            .filter(res -> res.getStatus() == ReservationStatus.CHECKED_OUT)
            .filter(res -> !res.getCheckOut().isBefore(startDate) && !res.getCheckIn().isAfter(endDate))
            .collect(Collectors.toList());

        LocalDate currentDate = startDate;
        while (!currentDate.isAfter(endDate)) {
            double dailyRevenue = 0;
            final LocalDate date = currentDate;
            for (Reservation res : reservations) {
                if (!date.isBefore(res.getCheckIn()) && date.isBefore(res.getCheckOut())) {
                    dailyRevenue += calculateDailyRevenue(res, date);
                }
            }
            report.append(currentDate).append(",").append(String.format("%.2f", dailyRevenue)).append("\n");
            currentDate = currentDate.plusDays(1);
        }

        return report.toString();
    }

    private double calculateDailyRevenue(Reservation reservation, LocalDate date) {
        long totalDays = java.time.temporal.ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
        return reservation.getTotalPrice() / totalDays;
    }
}

