        this.reservations = new ArrayList<>();
        this.roomService = roomService;
        this.pricingService = pricingService;
    }

    public Reservation createReservation(int roomNumber, LocalDate checkIn, LocalDate checkOut,
                                        int guestCount, String guestEmail, String guestIdentification,
                                        String guestIdentificationType, RatePlan ratePlan) {
        // Validate room exists
        Room room = roomService.getRoomByNumber(roomNumber)
            .orElseThrow(() -> new IllegalArgumentException("Room not found: " + roomNumber));

        // Validate room capacity
        if (guestCount > room.getType().getCapacity()) {
