package com.pousada.service;

import com.pousada.domain.RatePlan;
import com.pousada.domain.RoomType;
import com.pousada.util.MoneyRounder;
import java.time.LocalDate;
import java.time.Month;
import java.util.stream.LongStream;

public class PricingService {
    private static final double NON_REFUNDABLE_DISCOUNT = 0.15;

    public double calculatePrice(RoomType roomType, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
        long numberOfDays = java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);

        if (numberOfDays <= 0) {
            throw new IllegalArgumentException("Check-out must be after check-in");
        }

        double totalPrice = 0;

        LocalDate currentDate = checkIn;
        for (long i = 0; i < numberOfDays; i++) {
            double dailyRate = roomType.getDailyRate();
            if (isHighSeason(currentDate)) {
                dailyRate *= 1.5;
            }
            totalPrice += dailyRate;
            currentDate = currentDate.plusDays(1);
        }

        if (ratePlan == RatePlan.NON_REFUNDABLE) {
            totalPrice *= (1 - NON_REFUNDABLE_DISCOUNT);
        }

        return MoneyRounder.round(totalPrice);
    }

    private boolean isHighSeason(LocalDate date) {
        Month month = date.getMonth();
        int dayOfMonth = date.getDayOfMonth();

        // July
        if (month == Month.JULY) {
            return true;
        }

        // December 15 to February 28
        if (month == Month.DECEMBER && dayOfMonth >= 15) {
            return true;
        }

        if (month == Month.JANUARY || month == Month.FEBRUARY) {
            return true;
        }

        return false;
    }
}

